import {CoreFactory} from '../../core/core-factory';
import {Bumper} from '../../core/interfaces/bumper';
import {ClaudeService} from '../../core/services/bumpers/claude-bumper-service';
import {NpmService} from '../../core/services/bumpers/npm-bumper-service';
import {BumpCommand} from './bump-command/bump-command';

export class CliFactory {
  public getBumpCommand(bumpers: Bumper[]): BumpCommand {
    return new BumpCommand(
      bumpers,
      this.coreFactory.getSemverService(),
      this.coreFactory.getChangelogService(),
    );
  }

  public getNpmService(): NpmService {
    return this.coreFactory.getNpmService();
  }

  public getClaudeService(pluginDir: string): ClaudeService {
    return this.coreFactory.getClaudeService(pluginDir);
  }

  constructor(private readonly coreFactory: CoreFactory) {}

  static make(cwd: string): CliFactory {
    const coreFactory = CoreFactory.make(cwd);
    return new CliFactory(coreFactory);
  }
}
